  [CH("Three perspectives", "And a scholar each", [("Indology", "G. S. Ghurye: through texts", "Indology"), ("Structural-functionalism", "M. N. Srinivas: through fieldwork", "Structural"), ("Marxist", "A. R. Desai: through class", "Marxist")],
      "A: Indologists like G. S. Ghurye studied society through classical texts. | B: Srinivas used fieldwork in villages. A. R. Desai used class analysis."),
   QT("Book view vs field view", "What texts say, and what people actually do, can differ.",
      "A: Srinivas called it the book view versus the field view. | B: Texts and real life don't always match."),
   CH("Others to cite", "Also", [("Louis Dumont", "Purity and pollution", "Dumont"), ("D. P. Mukerji", "Tradition and modernity", "Mukerji")],
      "A: Cite Louis Dumont on purity and pollution, | B: and D. P. Mukerji on tradition.")],
